/**
 * Shared contract types - generated by openapi-typescript.
 * Do NOT hand-edit `src/generated/`. Run `pnpm contracts:build` to regenerate.
 */
import type { components, paths } from './generated/index';

export * from './generated/index';

/** 全部 OpenAPI 组件 schema 的快捷入口 */
export type Schemas = components['schemas'];

/** 取某个接口 200 响应的完整信封（{ code, message, data }） */
export type ResponseBody<
  P extends keyof paths,
  M extends keyof paths[P],
> = paths[P][M] extends {
  responses: { 200: { content: { 'application/json': infer Body } } };
}
  ? Body
  : never;

/** 取某个接口 200 响应里的 data 负载类型 */
export type ApiData<P extends keyof paths, M extends keyof paths[P]> =
  ResponseBody<P, M> extends { data: infer Data } ? Data : never;
